(function(g){'use strict';const KEY='voidos_app_permissions_v1';function read(){try{const v=JSON.parse(localStorage.getItem(KEY)||'{}');return v&&typeof v==='object'?v:{}}catch{return{}}}function write(v){try{localStorage.setItem(KEY,JSON.stringify(v));g.VoidEventBus?.emit('permissions:changed',{at:Date.now()});return true}catch{return false}}function get(app){const all=read();return all[String(app||'').toLowerCase()]||{enabled:true,grants:{}}}function setEnabled(app,enabled){const all=read(),k=String(app||'').toLowerCase(),current=all[k]||{enabled:true,grants:{}};current.enabled=!!enabled;all[k]=current;const ok=write(all);if(ok)g.VoidEventBus?.emit('app:enabled-changed',{app:k,enabled:!!enabled});return ok}function grant(app,permission,allowed){const all=read(),k=String(app||'').toLowerCase(),current=all[k]||{enabled:true,grants:{}};current.grants=current.grants||{};current.grants[String(permission)]=!!allowed;all[k]=current;const ok=write(all);if(ok)g.VoidEventBus?.emit('permission:changed',{app:k,permission,allowed:!!allowed});return ok}function isGranted(app,permission){const state=get(app);return state.grants?.[permission]===true}function canLaunch(app){return get(app).enabled!==false}function request(app,permission,reason){if(isGranted(app,permission))return true;const labels={network:'الاتصال بالمواقع الخارجية',storage:'الوصول إلى التخزين المحلي',notifications:'إرسال إشعارات'};const message='يطلب '+app+' صلاحية '+(labels[permission]||permission)+'.\nالسبب: '+(reason||'تحتاجها وظيفة داخل التطبيق')+'\n\nهل تسمح بها؟';let allow=false;try{allow=typeof g.confirm==='function'&&g.confirm(message)}catch{}if(allow)grant(app,permission,true);return allow}g.VoidPermissionManager={version:'2.0.0',key:KEY,read,get,setEnabled,grant,isGranted,canLaunch,request,list:()=>read()}})(window);
